//! Real LX7 load/store guests touch actual S3 GPIO/I2C/RMT/SPI MMIO.
//! These are original diagnostics, not manufacturer firmware boot acceptance.
use emu_core::{Bus,Core};
use esp_soc::{SocBus,Stop};
use esp32s3::board::{self,waveshare_extended::{Profile,memory_mib}};
const PC:u32=0x4037_0000;const GPIO:u32=0x6000_4000;
struct Guest {m:esp32s3::Machine}
impl Guest {
    fn new(name:&str)->Self {let mut m=esp32s3::machine([0;6]);m.bus.board=board::make_board(name).unwrap();m.bus.attach_board_devices();let(f,p)=memory_mib(name).unwrap_or((8,8));m.bus.set_flash_size(f<<20);m.bus.set_psram_size(p<<20).unwrap();m.bus.load_bytes(PC,&[0x32,0x64,0,0x52,0x24,0]).unwrap();m.cores[0].ps=0;m.cores[0].set_jit(false);Self{m}}
    fn put(&mut self,address:u32,value:u32){self.m.cores[0].pc=PC;self.m.cores[0].set_ar(4,address);self.m.cores[0].set_ar(3,value);assert!(matches!(self.m.run(1),Stop::MaxInsns));}
    fn get(&mut self,address:u32)->u32 {self.m.cores[0].pc=PC+3;self.m.cores[0].set_ar(4,address);assert!(matches!(self.m.run(1),Stop::MaxInsns));self.m.cores[0].get_ar(5)}
    fn route(&mut self,pin:u8,signal:u32){self.put(0x6000_9004+4*u32::from(pin),1<<12|1<<9);self.put(GPIO+0x554+4*u32::from(pin),signal);if signal==256{self.put(GPIO+if pin<32{0x24}else{0x30},1<<(pin%32));}}
    fn high(&mut self,pin:u8,value:bool){self.put(GPIO+if pin<32{if value{8}else{12}}else if value{20}else{24},1<<(pin%32));}
    fn i2c_route(&mut self,b:u32,sda:u8,scl:u8){for(p,s)in[(sda,90+b*2),(scl,89+b*2)]{self.route(p,s);self.put(GPIO+0x154+4*s,0x80|u32::from(p));}}
    fn i2c(&mut self,b:u32,address:u8,reg:u8,data:&[u8],n:u8)->Option<Vec<u8>>{
        let base=[0x6001_3000,0x6002_7000][b as usize];self.put(base+0x24,u32::MAX);self.put(base+0x18,3<<12);
        for v in[address<<1,reg].into_iter().chain(data.iter().copied()){self.put(base+0x1c,u32::from(v));}
        let mut commands=vec![6<<11,1<<11|1<<8|(data.len()+2)as u32];if n>0{self.put(base+0x1c,u32::from(address<<1|1));commands.extend([6<<11,1<<11|1<<8|1,3<<11|u32::from(n)]);}commands.push(2<<11);
        for(i,c)in commands.into_iter().enumerate(){self.put(base+0x58+4*i as u32,c);}self.put(base+4,1<<5);self.m.bus.tick(100_000);
        if self.get(base+0x20)&(1<<10)!=0{return None;}assert_ne!(self.get(base+0x20)&(1<<7),0);Some((0..n).map(|_|self.get(base+0x1c)as u8).collect())
    }
    fn rmt(&mut self,bytes:&[u8]) {let bits:Vec<bool>=bytes.iter().flat_map(|b|(0..8).map(move|i|b&(0x80>>i)!=0)).collect();for(i,&b)in bits.iter().enumerate(){self.put(0x6001_6800+4*i as u32,0x8000|if b{64|32<<16}else{32|64<<16});}self.put(0x6001_6800+4*bits.len()as u32,0);self.put(0x6001_6020,4<<16|1<<8|1);self.m.bus.tick(200_000);}
    fn diag(&self)->String {self.m.bus.board.hardware_diagnostics().unwrap()}
}
#[test]
fn all_exact_headless_skus_keep_memory_physical_keys_and_absent_devices(){
    for p in Profile::ALL {let mut g=Guest::new(p.name());let(f,r)=p.memory();assert_eq!(g.m.bus.flash.len(),f<<20);assert_eq!(g.m.bus.psram.len(),r<<20);assert_eq!(g.m.bus.board.named_pin("boot"),p.boot().then_some(0));assert!(g.m.bus.board.display().is_none());assert!(g.m.bus.board.camera_frame().is_none());assert!(g.m.bus.board.i2c_devices().is_empty());assert!(g.m.bus.board.sd_card_slot().is_none());if !p.eth(){assert!(g.m.bus.attach_sd_card(Box::new(esp_periph::sdmmc::MemStore(vec![0;1<<20])),Default::default()).is_err());}}
}
#[test]
fn tiny_and_relay6_exact_rmt_channels_and_coil_outputs_are_guest_driven(){
    for p in Profile::ALL{let mut g=Guest::new(p.name());let pin=p.led_pin();let wrong=if pin==21{38}else{21};g.route(wrong,81);g.rmt(&[0x12,0x34,0x56]);assert_eq!(g.m.bus.board.leds().unwrap().1,0);g.route(wrong,256);g.route(pin,81);g.rmt(&[0x12,0x34,0x56]);assert_eq!(g.m.bus.board.leds().unwrap().0,[if p==Profile::Relay6{[0x12,0x34,0x56]}else{[0x34,0x12,0x56]}]);g.put(GPIO+0x554+u32::from(pin)*4,81|1<<9);let v=g.m.bus.board.leds().unwrap().1;g.rmt(&[255;3]);assert_eq!(g.m.bus.board.leds().unwrap().1,v);}
    let mut g=Guest::new(Profile::Relay6.name());for pin in[1,2,41,42,45,46]{g.route(pin,256);g.high(pin,true);}assert!(g.diag().contains("\"relayCoilDrive\":[true,true,true,true,true,true]"));g.put(GPIO+0x34,1<<(45-32));assert!(g.diag().contains("\"relayCoilDrive\":[true,true,true,true,null,true]"));g.route(45,256);g.high(45,false);assert!(g.diag().contains("\"relayCoilDrive\":[true,true,true,true,false,true]"));g.route(21,256);g.high(21,true);assert!(g.diag().contains("\"buzzerGpioDrive\":true"));assert_eq!(g.m.bus.psram.len(),0);
}
impl Guest {
    fn spi(&mut self,bytes:&[u8])->Vec<u8>{let mut out=Vec::new();for chunk in bytes.chunks(64){for(i,w)in chunk.chunks(4).enumerate(){let mut data=[0;4];data[..w.len()].copy_from_slice(w);self.put(0x6002_4098+4*i as u32,u32::from_le_bytes(data));}self.put(0x6002_4010,1<<27|1<<28);self.put(0x6002_401c,(chunk.len()*8-1)as u32);self.put(0x6002_4000,1<<24);out.extend((0..chunk.len()).map(|i|((self.get(0x6002_4098+4*(i/4)as u32)>>((i%4)*8))&255)as u8));}out}
    fn sd_cmd(&mut self,c:u8,arg:u32)->Vec<u8>{let mut bytes=vec![0x40|c];bytes.extend(arg.to_be_bytes());let mut crc=0u8;for &v in &bytes{let mut b=v;for _ in 0..8{crc<<=1;if(b^crc)&0x80!=0{crc^=9;}b<<=1;}}bytes.push((crc&0x7f)<<1|1);self.spi(&bytes);self.spi(&[255;2])}
    fn sd_init(&mut self){self.route(4,256);self.high(4,true);self.spi(&[255;10]);self.high(4,false);assert_eq!(self.sd_cmd(0,0),[255,1]);assert_eq!(self.sd_cmd(8,0x1aa),[255,1]);assert_eq!(self.spi(&[255;4]),[0,0,1,0xaa]);for _ in 0..2{self.sd_cmd(55,0);self.sd_cmd(41,1<<30);}}
    fn sd_read(&mut self)->Vec<u8>{assert_eq!(self.sd_cmd(17,3),[255,0]);assert_eq!(self.spi(&[255;2]),[255,0xfe]);let out=self.spi(&[255;512]);self.spi(&[255;2]);out}
}
#[test]
fn all_eight_eth_skus_roundtrip_real_spi_sd_blocks_and_reject_wrong_pads_ejection_and_partial_write(){
    for p in Profile::ALL.into_iter().filter(|p|p.eth()){let mut g=Guest::new(p.name());g.m.bus.attach_sd_card(Box::new(esp_periph::sdmmc::MemStore(vec![0;1<<20])),Default::default()).unwrap();g.route(7,101);g.route(6,103);g.route(5,256);g.put(GPIO+0x28,1<<5);g.put(GPIO+0x154+4*102,0x80|5);g.put(0x6002_4020,0x3f);g.sd_init();assert_eq!(g.sd_cmd(24,3),[255,0]);let mut data=vec![0xfe];data.extend((0..512).map(|i|(i%251)as u8));data.extend([255;2]);g.spi(&data);assert_eq!(g.spi(&[255]),[5]);assert_eq!(g.sd_read(),data[1..513]);g.route(6,256);assert_eq!(g.sd_cmd(58,0),[255;2]);g.route(6,103);g.put(GPIO+0x154+4*102,0x80|4);assert_eq!(g.sd_cmd(58,0),[255;2]);g.put(GPIO+0x154+4*102,0x80|5);g.high(4,true);g.high(4,false);assert_eq!(g.sd_cmd(24,3),[255,0]);g.spi(&[0xfe,9,9,9]);g.high(4,true);g.high(4,false);assert_eq!(g.sd_read(),data[1..513]);g.m.bus.board.set_sd_card_present(false);assert_eq!(g.sd_cmd(0,0),[255;2]);g.m.bus.board.set_sd_card_present(true);assert_eq!(g.sd_cmd(0,0),[255;2]);g.sd_init();assert_eq!(g.sd_read(),data[1..513]);g.route(8,256);g.high(8,false);assert!(g.diag().contains(if p.camera(){"\"cameraEnableHigh\":false"}else{"\"cameraEnableHigh\":null"}));}
}
fn lcd_serial(g:&mut Guest,data:bool,value:u8){g.put(0x6002_4010,1<<31|1<<30);g.put(0x6002_4014,7<<27);g.put(0x6002_4018,if data{0x80}else{0});g.put(0x6002_4004,u32::from(value)<<24);g.put(0x6002_4000,1<<24);}
fn lcd_route(g:&mut Guest){for(pin,s)in[(2,101),(1,103),(42,110),(41,154),(40,150),(39,152),(38,151)]{g.route(pin,s);}for(i,pin)in[5,45,48,47,21,14,13,12,11,10,9,46,3,8,18,17].into_iter().enumerate(){g.route(pin,133+i as u32);}g.route(6,256);g.high(6,false);g.put(0x6002_4020,0x3e);}
fn lcd_dma(g:&mut Guest,wide:bool){const DESC:u32=0x3fc88000;const DATA:u32=0x3fc8a000;let total:u32=480*480*2;let mut data=vec![0u8;total as usize];for(i,pixel)in[(240*480+240,0xf800u16),(240*480+241,0x07e0),(0,0x001f)]{data[2*i..2*i+2].copy_from_slice(&pixel.to_le_bytes());}g.m.bus.load_bytes(DATA,&data).unwrap();let(mut pos,mut index)=(0,0);while pos<total{let len=(total-pos).min(4092);let last=pos+len==total;for(i,v)in[1<<31|u32::from(last)<<30|len<<12|len,DATA+pos,if last{0}else{DESC+12*(index+1)}].into_iter().enumerate(){g.put(DESC+12*index+4*i as u32,v);}pos+=len;index+=1;}for(a,v)in[(0x60041014,0),(0x600c001c,1<<8),(0x6003f0a8,5),(0x6003f080,(DESC&0xfffff)|(1<<21)),(0x60041000,(1<<31)|(3<<29)|(20<<9)|(1<<6)),(0x60041020,(479<<8)|(501<<20)),(0x6004101c,(1<<31)|(479<<11)|(518<<21)),(0x60041014,(1<<27)|(1<<24)|if wide{1<<23}else{0})]{g.put(a,v);}g.m.bus.tick(8_000_000);g.m.bus.refresh_board_outputs();}
#[test]
fn three_exact_rgb_kits_use_gpio42_select_tca_p2_reset_p1_backlight_and_actual_guest_lcd_dma(){
    for name in["waveshare-s3-lcd-driver-21","waveshare-s3-lcd-driver-28","waveshare-s3-lcd-driver-4"]{let mut g=Guest::new(name);g.i2c_route(0,15,7);g.i2c(0,0x20,3,&[0xf8],0).unwrap();g.i2c(0,0x20,1,&[0xff],0).unwrap();lcd_route(&mut g);g.put(0x6002_4020,0x3f);lcd_serial(&mut g,false,0x11);lcd_serial(&mut g,false,0x29);lcd_dma(&mut g,true);assert!(g.m.bus.board.display().unwrap().2.iter().all(|&p|p==0),"disabled MCU CS cannot initialize glass");g.put(0x6002_4020,0x3e);lcd_serial(&mut g,false,0x11);lcd_serial(&mut g,false,0x29);lcd_dma(&mut g,true);let f=g.m.bus.board.display().unwrap();assert_eq!([f.2[240*480+240],f.2[240*480+241]],[0xf800,0x07e0],"{name} {}",g.m.bus.board.report());assert_eq!(f.2[0],if name.ends_with("-4"){0x001f}else{0});let frames=g.m.bus.board.display_frames();g.route(5,132);lcd_dma(&mut g,true);assert_eq!(g.m.bus.board.display_frames(),frames);lcd_route(&mut g);lcd_dma(&mut g,false);assert_eq!(g.m.bus.board.display_frames(),frames);g.i2c(0,0x20,1,&[0xfd],0).unwrap();assert!(g.m.bus.board.display().unwrap().2.iter().all(|&p|p==0),"BL_EN P1 disables light");g.i2c(0,0x20,1,&[0xfb],0).unwrap();g.i2c(0,0x20,1,&[0xff],0).unwrap();assert!(g.m.bus.board.display().unwrap().2.iter().all(|&p|p==0),"reset P2 clears init");assert_eq!(g.i2c(0,0x51,0,&[],1),None);assert_eq!(g.i2c(0,0x6b,0,&[],1),None);assert!(g.m.bus.attach_sd_card(Box::new(esp_periph::sdmmc::MemStore(vec![0;1<<20])),Default::default()).is_err());}
}
#[test]
fn bare_driver_has_only_tca_and_cst820_touch_reset_is_p0_not_integrated_board_p1(){
    let mut bare=Guest::new("waveshare-s3-lcd-driver");bare.i2c_route(0,15,7);assert_eq!(bare.i2c(0,0x20,3,&[],1),Some(vec![255]));for a in[0x15,0x14,0x5d,0x51,0x6b]{assert_eq!(bare.i2c(0,a,0,&[],1),None);}assert!(bare.m.bus.board.display().is_none());assert!(!bare.m.bus.board.set_imu_motion(1));
    let mut g=Guest::new("waveshare-s3-lcd-driver-21");g.i2c_route(0,15,7);g.m.bus.touch_input(450,123,true);assert_eq!(g.i2c(0,0x15,2,&[],5),Some(vec![1,1,194,0,123]));g.i2c(0,0x20,3,&[0xf8],0).unwrap();g.i2c(0,0x20,1,&[0xfd],0).unwrap();assert_eq!(g.i2c(0,0x15,2,&[],1),Some(vec![1]),"P1 is backlight, not touch reset");g.i2c(0,0x20,1,&[0xfe],0).unwrap();assert_eq!(g.i2c(0,0x15,2,&[],1),None);g.i2c(0,0x20,1,&[0xff],0).unwrap();assert_eq!(g.i2c(0,0x15,2,&[],1),Some(vec![0]));g.i2c_route(0,7,15);assert_eq!(g.i2c(0,0x20,0,&[],1),None);
}
#[test]
fn gt911_kit_address_strap_reset_and_inverse_ledc_are_real_guest_register_paths(){
    for name in["waveshare-s3-lcd-driver-28","waveshare-s3-lcd-driver-4"]{let mut g=Guest::new(name);g.i2c_route(0,15,7);assert_eq!(g.i2c(0,0x14,0x81,&[0x46],4),Some(vec![0xe0,1,0xe0,1]));g.i2c(0,0x20,3,&[0xf8],0).unwrap();g.i2c(0,0x20,1,&[0xfe],0).unwrap();assert_eq!(g.i2c(0,0x14,0x81,&[0x46],4),None);g.route(16,256);g.high(16,false);g.i2c(0,0x20,1,&[0xff],0).unwrap();g.put(GPIO+0x28,1<<16);assert_eq!(g.i2c(0,0x14,0x81,&[0x46],4),None);assert_eq!(g.i2c(0,0x5d,0x81,&[0x46],4),Some(vec![0xe0,1,0xe0,1]));g.i2c(0,0x5d,0x81,&[0x4e,0],0).unwrap();g.m.bus.touch_input(345,234,true);g.m.bus.tick(3_000_000);let reply=g.i2c(0,0x5d,0x81,&[0x4e],9).unwrap();assert_eq!(reply[0]&0x8f,0x81);assert_eq!(&reply[2..6],&[0x59,1,0xea,0]);
        lcd_route(&mut g);lcd_serial(&mut g,false,0x11);lcd_serial(&mut g,false,0x29);lcd_dma(&mut g,true);let at=240*480+240;assert_eq!(g.m.bus.board.display().unwrap().2[at],0xf800);for(a,v)in[(0x600c0018,1<<11),(0x600190d0,3),(0x600190a0,8|(256<<4)|(1<<25)),(0x60019008,64<<4),(0x6001900c,1<<31),(0x60019000,4|(1<<4))]{g.put(a,v);}g.m.bus.tick(10000);g.route(6,73);g.m.bus.refresh_board_outputs();assert_eq!(g.m.bus.board.display().unwrap().2[at],23<<11);g.put(GPIO+0x554+4*6,73|1<<9);g.m.bus.refresh_board_outputs();assert_eq!(g.m.bus.board.display().unwrap().2[at],7<<11);g.put(GPIO+0x28,1<<6);g.m.bus.refresh_board_outputs();assert_eq!(g.m.bus.board.display().unwrap().2[at],0);
    }
}
